import{_ as o,o as a,c as r,a0 as t}from"./chunks/framework.DQOulFGV.js";const q=JSON.parse('{"title":"喵喵答疑 (FAQ) 🐾","description":"","frontmatter":{},"headers":[],"relativePath":"meow/guide/faq.md","filePath":"meow/guide/faq.md"}'),d={name:"meow/guide/faq.md"};function n(s,e,c,i,l,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="喵喵答疑-faq-🐾" tabindex="-1">喵喵答疑 (FAQ) 🐾 <a class="header-anchor" href="#喵喵答疑-faq-🐾" aria-label="Permalink to &quot;喵喵答疑 (FAQ) 🐾&quot;">​</a></h1><p>本喵整理了主人在使用 KernelEX 时可能会遇到的一些小疑问喵~</p><hr><h3 id="q1-为什么像-top、htop、vim-这类程序在终端里排版乱糟糟的喵" tabindex="-1">Q1: 为什么像 <code>top</code>、<code>htop</code>、<code>vim</code> 这类程序在终端里排版乱糟糟的喵？ <a class="header-anchor" href="#q1-为什么像-top、htop、vim-这类程序在终端里排版乱糟糟的喵" aria-label="Permalink to &quot;Q1: 为什么像 `top`、`htop`、`vim` 这类程序在终端里排版乱糟糟的喵？&quot;">​</a></h3><p><strong>A</strong>：因为本喵是基于标准管道（Pipe 管道传递 <code>stdin</code>/<code>stdout</code>/<code>stderr</code>）搭建的图形化辅助执行器，<strong>不是</strong>基于 Linux 原生 PTY 伪终端的完整终端模拟器喵。所以那些依赖 ncurses / 绝对光标定位的全屏程序不能正常画出来喵。本喵最擅长的是为主人跑自动化 Shell 脚本、后台服务、刷写模块与批处理工具喵~</p><hr><h3 id="q2-为什么二进制可执行程序要叫-so-喵" tabindex="-1">Q2: 为什么二进制可执行程序要叫 <code>.so</code> 喵？ <a class="header-anchor" href="#q2-为什么二进制可执行程序要叫-so-喵" aria-label="Permalink to &quot;Q2: 为什么二进制可执行程序要叫 `.so` 喵？&quot;">​</a></h3><p><strong>A</strong>：在 Android 世界里，通常只有特定受保护目录才有执行权限，把 ELF 原生二进制命名为 <code>.so</code> 是 Magisk 模块和安卓玩机圈里的通用秘密惯例喵。本喵天生支持直接执行 <code>.so</code> 和 <code>.sh</code>，并且执行前会自动为主人补齐 <code>chmod 777</code> 满权喵！</p><hr><h3 id="q3-任务在后台跑着跑着被系统杀掉了怎么办喵" tabindex="-1">Q3: 任务在后台跑着跑着被系统杀掉了怎么办喵？ <a class="header-anchor" href="#q3-任务在后台跑着跑着被系统杀掉了怎么办喵" aria-label="Permalink to &quot;Q3: 任务在后台跑着跑着被系统杀掉了怎么办喵？&quot;">​</a></h3><p><strong>A</strong>：</p><ol><li>请主人前往「设置」或权限检查门，点击「<strong>申请忽略电池优化</strong>」，把本喵加入系统电池白名单喵；</li><li>在很多厂商定制系统（如 HyperOS、OriginOS、ColorOS）里，建议主人在最近任务列表给本喵<strong>挂上一把小锁</strong>，并开启「允许自启动」权限喵。</li></ol><hr><h3 id="q4-换了字体之后想换回默认字体怎么操作喵" tabindex="-1">Q4: 换了字体之后想换回默认字体怎么操作喵？ <a class="header-anchor" href="#q4-换了字体之后想换回默认字体怎么操作喵" aria-label="Permalink to &quot;Q4: 换了字体之后想换回默认字体怎么操作喵？&quot;">​</a></h3><p><strong>A</strong>：进入底栏「设置」页面，找到「自定义软件字体」卡片，点击齿轮图标，再点击「<strong>恢复默认字体</strong>」，本喵就会瞬间变回内置默认字体啦喵~</p><hr><h3 id="q5-「添加到-kernelex」时的「独立文件夹」是干什么的喵" tabindex="-1">Q5: 「添加到 KernelEX」时的「独立文件夹」是干什么的喵？ <a class="header-anchor" href="#q5-「添加到-kernelex」时的「独立文件夹」是干什么的喵" aria-label="Permalink to &quot;Q5: 「添加到 KernelEX」时的「独立文件夹」是干什么的喵？&quot;">​</a></h3><p><strong>A</strong>：当多个脚本带有同名配置文件（比如都叫 <code>config.json</code>）时，如果全堆在同一个大盒子里容易互相盖住喵。开启独立文件夹后，本喵会在 <code>/data/adb/KernelEX/</code> 下以 <code>[名称]_[时间戳]</code> 自动建立独立小窝进行隔离存储喵！</p>',18)])])}const g=o(d,[["render",n]]);export{q as __pageData,g as default};
